{{ config(materialized='table', partition_by={'field':'transaction_date','data_type':'date'}, cluster_by=['account_id','transaction_type_id']) }}
with raw_typed as (
  select safe_cast(TransactionID as int64) transaction_id,safe_cast(AccountID as int64) account_id,safe_cast(TransactionTypeID as int64) transaction_type_id,safe_cast(TransactionTs as timestamp) transaction_ts,date(safe_cast(TransactionTs as timestamp)) transaction_date,safe_cast(Amount as numeric) amount,upper(trim(Currency)) currency,upper(trim(Channel)) channel,upper(trim(MerchantCategory)) merchant_category,trim(Reference) reference,batch_id,business_date,source_file,source_row_number,ingestion_ts,count(*) over(partition by TransactionID) duplicate_count,row_number() over(partition by TransactionID order by ingestion_ts desc, source_row_number desc) rn
  from {{ source('bronze','TRANSACTIONS_bronze') }}
), deduped as (select * except(rn) from raw_typed where rn=1), enriched as (
  select t.*,a.customer_id,a.account_type_id,a.branch_id,a.currency as account_currency,a.open_date,a.close_date,a.status as account_status,tt.category transaction_category,tt.direction,tt.is_cash_proxy,a.customer_id is not null as has_account_reference,tt.transaction_type is not null as has_transaction_type_reference,t.currency != a.currency as is_currency_mismatch,t.transaction_date < a.open_date or (a.close_date is not null and t.transaction_date > a.close_date) as is_invalid_transaction_date,abs(t.amount) > {{ var('suspicious_transaction_threshold',100000) }} as is_high_value,countif(tt.is_cash_proxy and t.channel in ('BRANCH','ATM') and abs(t.amount) between {{ var('structuring_lower_bound',9000) }} and {{ var('structuring_upper_bound',10000) }}) over(partition by t.account_id order by unix_seconds(t.transaction_ts) range between {{ var('structuring_window_seconds',3600) }} preceding and current row) >= {{ var('structuring_min_count',3) }} as is_structuring_candidate,(a.status='DORMANT' and count(*) over(partition by t.account_id order by unix_seconds(t.transaction_ts) range between {{ var('structuring_window_seconds',3600) }} preceding and current row) >= 3) as is_dormant_reactivation_burst
  from deduped t left join {{ ref('slv_accounts') }} a using(account_id) left join {{ ref('slv_transaction_types') }} tt using(transaction_type_id)
)
select *,not is_invalid_transaction_date and has_account_reference and has_transaction_type_reference and amount is not null and transaction_ts is not null as is_valid_record from enriched
